const { coords, width, height } = $input.first().json;
const boxes = coords.map((c) => {
  const a = c.box_2d;
  if (
    !Array.isArray(a) ||
    a.length !== 4 ||
    a.some((v) => !Number.isFinite(v) || v < 0 || v > 1000) ||
    a[0] > a[2] ||
    a[1] > a[3]
  )
    throw Error("Invalid box");
  return {
    xmin: (a[1] * width) / 1000,
    ymin: (a[0] * height) / 1000,
    xmax: (a[3] * width) / 1000,
    ymax: (a[2] * height) / 1000,
  };
});
return {
  json: { boxes, width: Number(width), height: Number(height) },
  binary: $("Get Test Image").first().binary,
};

const b = await this.helpers.getBinaryDataBuffer(0, "data"),
  { boxes, width, height } = $json,
  mime = $input.item.binary.data.mimeType;
if (!["image/jpeg", "image/png"].includes(mime)) throw Error("Unsupported image");
const rects = boxes
  .map(
    (x) =>
      `<rect x="${x.xmin}" y="${x.ymin}" width="${x.xmax - x.xmin}" height="${x.ymax - x.ymin}" fill="none" stroke="#ff00f2" stroke-opacity="0.47" stroke-width="4"/>`,
  )
  .join("");
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><image width="${width}" height="${height}" href="data:${mime};base64,${b.toString("base64")}"/>${rects}</svg>`;
return {
  json: { boxes },
  binary: {
    data: await this.helpers.prepareBinaryData(Buffer.from(svg), "detections.svg", "image/svg+xml"),
  },
};

const b = await this.helpers.getBinaryDataBuffer(0, "data");
let width, height, mime;
if (b[0] === 255 && b[1] === 216) {
  mime = "image/jpeg";
  let p = 2;
  while (p + 9 < b.length) {
    if (b[p++] !== 255) continue;
    let m = b[p++];
    while (m === 255) m = b[p++];
    if (m === 216 || m === 217 || (m >= 208 && m <= 215)) continue;
    const n = b.readUInt16BE(p);
    if (n < 2 || p + n > b.length) throw Error("Invalid JPEG");
    if ([192, 193, 194, 195, 197, 198, 199, 201, 202, 203, 205, 206, 207].includes(m)) {
      height = b.readUInt16BE(p + 3);
      width = b.readUInt16BE(p + 5);
      break;
    }
    p += n;
  }
} else if (b[0] === 137 && b[1] === 80 && b[2] === 78 && b[3] === 71) {
  mime = "image/png";
  width = b.readUInt32BE(16);
  height = b.readUInt32BE(20);
}
if (!width || !height) throw Error("Expected JPEG or PNG");
return {
  json: { size: { width, height }, imageBase64: b.toString("base64"), mime },
  binary: $input.item.binary,
};
